<?php if(!defined('ABSPATH')){exit;}$article=$state->article();$view=$article?(new AICS_Manual_Featured_Image_Service())->view($article['id'],get_current_user_id()):array();$attachment=$view['attachment']??null;$prompt=(string)($view['image_prompt']??''); ?>
