<?php else:?><form class="aics-wizard-form" data-operation="save_image_prompt"><div class="aics-field aics-field--full"><label class="aics-field-label" for="aics-featured-image-prompt"><?php esc_html_e('Featured Image Prompt','ai-content-studio');?></label><p class="description"><?php esc_html_e('This prompt was created from your article. Review or edit it before generating the featured image.','ai-content-studio');?></p><textarea class="large-text" rows="14" id="aics-featured-image-prompt" name="featured_image_prompt" maxlength="5000" required><?php echo esc_textarea($prompt);?></textarea></div><div class="aics-wizard-actions"><?php if(!empty($view['provider_ready'])):?><button class="button button-primary" type="submit" data-aics-operation="generate_image"><?php esc_html_e('Generate Featured Image','ai-content-studio');?></button><?php else:?><p><?php esc_html_e('Configure image generation in Settings, or continue without an image.','ai-content-studio');?></p><?php endif;?><button class="button" type="button" data-aics-refresh-image-prompt><?php esc_html_e('Refresh Prompt from Article','ai-content-studio');?></button><button class="button" type="submit"><?php esc_html_e('Save Prompt','ai-content-studio');?></button></div></form><?php endif;?>
